<script lang="ts">
import Icon from './Icon.svelte';import Timeline from './Timeline.svelte';import OfficeHistory from './OfficeHistory.svelte';import PeriodDialog from './PeriodDialog.svelte';import {loadHistory,type HistoryRange,type HistorySnapshot} from './bridge';import {dateText} from './calendar';
let {profile,period,language,t,revision=0}:{profile:string;period:string;language:string;t:(key:string)=>string;revision?:number}=$props();let selection=$state<HistoryRange>({period:'all'});let data=$state<HistorySnapshot|null>(null);let section=$state('history');let loading=$state(false);let failed=$state(false);let choosing=$state(false);
$effect(()=>{void profile;selection={period:period==='today'?'today':'all'};});
$effect(()=>{const id=profile;const range=selection;let current=true;loading=true;failed=false;data=null;loadHistory(id,range).then(value=>{if(current)data=value;}).catch(()=>{if(current)failed=true;}).finally(()=>{if(current)loading=false;});return()=>{current=false;};});
$effect(()=>{revision;const id=profile;const range=selection;let current=true;loadHistory(id,range).then(value=>{if(current){data=value;failed=false;}}).catch(()=>{if(current)failed=true;});return()=>{current=false;};});
let caption=$derived(selection.period==='range'?`${dateText(selection.start)} — ${dateText(selection.end)}`:t(selection.period==='today'?'Сегодня':'Все дни'));
</script>
<section class="statistics-history"><div class="history-toolbar"><div class="history-tabs" role="tablist" aria-label={t('История поиска')}><button role="tab" aria-selected={section==='history'} class:active={section==='history'} onclick={()=>section='history'}>{t('История поиска')}</button><button role="tab" aria-selected={section==='offices'} class:active={section==='offices'} onclick={()=>section='offices'}>{t('Офисы')} · {data?.offices.length??'—'}</button></div><button class="period-button" onclick={()=>choosing=true}><Icon name="calendar_days"/>{t('Период')} · {caption}</button></div>{#if loading}<p class="muted" role="status">{t('Загрузка статистики…')}</p>{:else if failed}<p class="error" role="alert">{t('Не удалось прочитать историю поиска')}</p>{:else if section==='offices'}<OfficeHistory offices={data?.offices??[]} {language} {t}/>{:else}<Timeline rows={data?.timeline??[]} {profile} {selection} {language} {t}/>{/if}
{#if choosing}<PeriodDialog {selection} bounds={data?.bounds??null} {language} {t} onclose={()=>choosing=false} onapply={value=>{selection=value;choosing=false;}}/>{/if}</section>
<style>.statistics-history{border-top:1px solid var(--line);margin-top:24px;padding-top:16px}.history-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:12px}.history-tabs{display:flex;gap:16px}.history-tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;background:none;padding:10px 0;color:var(--muted)}.history-tabs button.active{color:var(--text);border-color:var(--accent)}.period-button{padding:8px 12px;min-width:160px}</style>
